// cam-bench: globals shim + loader for the bundled kiri minion inside a
// node worker_thread. The browser Worker global wires `self.onmessage` and
// `self.postMessage`; worker_threads does neither, so both are bridged here.
// The minion bundle (kiri-pool.mjs) is generated by bench.mjs next to this
// file's directory in the bench temp workspace.
import fs from 'fs';
import path from 'path';
import { parentPort } from 'worker_threads';
import { pathToFileURL, fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
// bench workspace root passed via env by bench.mjs: holds wasm/ copies
const WORK = process.env.CAM_BENCH_WORK || HERE;

globalThis.self = globalThis;
Object.defineProperty(globalThis, 'navigator', {
    value: { hardwareConcurrency: 1, userAgent: 'cam-bench' },
    configurable: true,
});
globalThis.atob = (s) => Buffer.from(s, 'base64').toString('binary');
globalThis.btoa = (s) => Buffer.from(s, 'binary').toString('base64');
globalThis.fetch = function (url) {
    if (typeof url === 'string' && url.includes('.wasm')) {
        const p = path.join(WORK, url);
        const buf = fs.readFileSync(p);
        return Promise.resolve({
            arrayBuffer: () => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength),
        });
    }
    return Promise.reject(new Error('fetch unsupported: ' + url));
};

// browser-worker semantics: message value wrapped in an {data} event
parentPort.on('message', (v) => {
    if (globalThis.onmessage) globalThis.onmessage({ data: v });
});
// worker_threads does not expose a global postMessage in ESM workers
globalThis.postMessage = (msg, transfer) => parentPort.postMessage(msg, transfer || []);

await import(pathToFileURL(path.join(HERE, 'kiri-pool.mjs')).href);
